import java.util.Scanner;

public class Main {
    static final int MAX_DIM = 31;
    static final int MAX_LEVEL = 71;
    static final long MOD = 1000000007L;

    static class Matrix {
        long[][] mat;
        int dimension;

        public Matrix(int n) {
            this.dimension = n;
            mat = new long[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    mat[i][j] = 0;
                }
            }
            for (int i = 0; i < n; i++) {
                mat[i][i] = 1;
            }
        }

        public Matrix multiply(Matrix b) {
            Matrix res = new Matrix(dimension);
            for (int i = 0; i < dimension; i++) {
                for (int j = 0; j < dimension; j++) {
                    long sum = 0;
                    for (int k = 0; k < dimension; k++) {
                        sum += this.mat[i][k] * b.mat[k][j];
                        sum %= MOD;
                    }
                    res.mat[i][j] = sum;
                }
            }
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        Matrix[][] M = new Matrix[MAX_LEVEL][MAX_DIM];
        for (int i = 0; i < MAX_LEVEL; i++) {
            for (int j = 0; j < MAX_DIM; j++) {
                M[i][j] = null;
            }
        }

        for (int i = 0; i < k; i++) {
            M[0][i] = new Matrix(k + 1);
            for (int j = 0; j <= k; j++) {
                M[0][i].mat[i][j] = 1;
            }
        }

        long[] powerArr = new long[100];
        int levelCount = 2;
        powerArr[0] = 1;
        powerArr[1] = k;
        while (powerArr[levelCount - 1] <= n / k) {
            powerArr[levelCount] = powerArr[levelCount - 1] * k;
            levelCount++;
        }

        for (int i = 1; i < levelCount; i++) {
            M[i][0] = new Matrix(k + 1);
            for (int j = 1; j < k; j++) {
                M[i][j] = M[i - 1][j - 1].multiply(M[i][j - 1]);
            }
            Matrix prod = new Matrix(k + 1);
            for (int j = k - 1; j >= 0; j--) {
                prod = prod.multiply(M[i - 1][j]);
                M[i][j] = M[i][j].multiply(prod);
            }
        }

        Matrix ans = new Matrix(k + 1);
        int cIdx = 0;
        for (int i = levelCount - 1; i >= 0; i--) {
            while (powerArr[i] <= n) {
                n -= powerArr[i];
                ans = M[i][cIdx].multiply(ans);
                cIdx++;
                cIdx %= k;
            }
        }

        long totalSum = 0;
        for (int i = 0; i <= k; i++) {
            totalSum += ans.mat[i][k];
            totalSum %= MOD;
        }

        System.out.println(totalSum);
        sc.close();
    }
}

